from pathlib import Path
import html, json
from urllib.parse import quote
from markdown_it import MarkdownIt

OUT = Path(__file__).resolve().parents[1]
inventory=json.loads((OUT/'evidence/source-inventory.json').read_text())
files=inventory['files']
payload=[{k:f[k] for k in ['path','name','module','lines','role','declarations','dependencies','dependents','package_refs']} for f in files]
md=MarkdownIt('commonmark',{'html':False}).enable('table')
chapters=[('README.md','总体结论'),('01-ARCHITECTURE.md','程序如何运行'),('03-QUALITY-AND-BUGS.md','质量与缺陷'),('04-PERFORMANCE.md','性能分析'),('05-RECOMMENDATIONS.md','整合与产品建议'),('06-ACCEPTANCE.md','验收矩阵')]
articles=[]
for filename,title in chapters:
    content=md.render((OUT/filename).read_text())
    # Local source citations keep their exact path and line as text; file links open the source.
    import re
    content=re.sub(r'href="(/home/[^"\n]+?):(\d+)"',lambda m:'href="/source?file='+quote(str(Path(m[1]).relative_to(OUT.parents[2])))+'#L'+m[2]+'"',content)
    articles.append('<details class="chapter"><summary>'+html.escape(title)+'</summary><article>'+content+'</article></details>')
